const _poly = require("_poly");
module.exports = {
  set_angle(ch, deg) {
    const cid = Math.floor(Number(ch) || 0);
    const d = Math.max(0, Math.min(180, Math.floor(Number(deg) || 90)));
    if (cid === 1) {
      _poly.sim_set("tilt_deg", d);
    } else {
      _poly.sim_set("pan_deg", d);
    }
  },
  center_all() {
    _poly.sim_set("pan_deg", 90);
    _poly.sim_set("tilt_deg", 90);
  },
};
